import {createWorld,T} from './world.js';
const $=id=>document.getElementById(id),keys=new Set();let world;
try{world=createWorld($('world'));}catch(e){$('loading').innerHTML='<span class="loading-mark">N↟</span><p>无法启动 3D 引擎</p><p>请使用支持 WebGL 的浏览器，并开启硬件加速后刷新。</p>';console.error(e);throw e;}
const state={mode:'intro',x:4,y:1.08,z:.9,vx:0,vy:0,vz:0,gravity:-1,grounded:true,oxygen:100,health:100,energy:100,time:360,elapsed:0,flips:0,coreCount:0,logCount:0,sector:0,checkpoint:4,invincible:0,flipCooldown:0,sound:false};
const sectors=[{name:'破损生活舱',en:'HABITAT DECK',objective:'恢复生活舱能源核心',hint:'按 Q 翻转，沿天花板绕过裂口。核心位于上方。'},{name:'激光维修廊',en:'MAINTENANCE',objective:'穿越激光阵列，回收核心',hint:'红光亮起时避开对应高度；熄灭后安全通过。'},{name:'失稳反应堆',en:'REACTOR CORE',objective:'解除护罩，恢复最终核心',hint:'沿天花板越过电弧，找到上方的护罩控制器。'}];
let simTime=0,lastTime=performance.now(),accumulator=0,toastTimeout,commsTimeout,closest=null,audioContext,master,ambient,started=false,helpPrevious='intro',cameraKick=0,walkTime=0,shownOxygen=false,shownGap=false,shownSecond=false,shownFinal=false,shownLowG=false;
let best=null;try{best=JSON.parse(localStorage.getItem('nullshift-best'));if(best)$('best-record').textContent=`本机最佳纪录 ${formatTime(best.time)} · ${best.rank} 评级`;}catch{}
function formatTime(s){const n=Math.max(0,Math.ceil(s));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function toast(msg){$('toast').textContent=msg;$('toast').classList.remove('hidden');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.add('hidden'),3300);}
function comms(msg,duration=7000){$('comms-text').textContent=msg;$('comms').classList.add('visible');clearTimeout(commsTimeout);commsTimeout=setTimeout(()=>$('comms').classList.remove('visible'),duration);}
function audioInit(){if(audioContext)return;try{audioContext=new(window.AudioContext||window.webkitAudioContext)();master=audioContext.createGain();master.gain.value=state.sound?.2:0;master.connect(audioContext.destination);ambient=audioContext.createGain();ambient.gain.value=.07;ambient.connect(master);for(const f of[48,72,96]){const osc=audioContext.createOscillator();osc.type='sine';osc.frequency.value=f;osc.connect(ambient);osc.start();}}catch{}}
function sound(type){if(!state.sound)return;audioInit();if(!audioContext)return;audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain(),t=audioContext.currentTime;osc.connect(gain);gain.connect(master);osc.type=type==='hurt'?'sawtooth':'sine';const notes={flip:[260,720,.45],pickup:[660,1320,.3],hurt:[100,35,.3],jump:[190,310,.18],open:[400,850,.6],win:[523,1046,1.5],click:[300,450,.08]};const [a,b,d]=notes[type]||notes.click;osc.frequency.setValueAtTime(a,t);osc.frequency.exponentialRampToValueAtTime(b,t+d);gain.gain.setValueAtTime(.35,t);gain.gain.exponentialRampToValueAtTime(.001,t+d);osc.start();osc.stop(t+d);}
function setSound(v){state.sound=v;$('sound-btn').classList.toggle('sound-on',v);$('sound-btn').setAttribute('aria-label',v?'关闭声音':'开启声音');audioInit();if(audioContext)audioContext.resume();if(master)master.gain.setTargetAtTime(v?.2:0,audioContext.currentTime,.1);}
function start(){if(state.mode!=='intro')return;started=true;state.mode='playing';document.body.classList.add('playing');$('intro').classList.add('hidden');$('modal').classList.add('hidden');setSound(true);sound('open');comms('07，先按 D 向前移动。裂口前按 Q，天花板就是你的新地面。',10000);updateHUD();}
function flip(){if(state.mode!=='playing')return;if(state.flipCooldown>0)return;if(state.energy<25){toast('重力电容不足，落稳后稍等充能。');sound('hurt');return;}state.energy-=25;state.gravity*=-1;state.grounded=false;state.vy=state.gravity*1.5;state.flips++;state.flipCooldown=.65;cameraKick=.22;sound('flip');updateHUD();}
function jump(){if(state.mode!=='playing')return;if(state.grounded){state.vy=-state.gravity*6.4;state.grounded=false;sound('jump');}else if(state.energy>=12){state.vy+=-state.gravity*3;state.energy-=12;world.player.flame.visible=true;setTimeout(()=>world.player.flame.visible=false,220);sound('jump');}}
function distance(o){return Math.hypot(state.x-o.x,state.y-o.y,state.z-o.z);}
const logTexts=['船员日志 01：撞击发生在 03:17。我们的重力模块仍能独立工作。记住：方向由你决定。','船员日志 02：激光安全系统每 5.8 秒循环一次。别急，熄灭的窗口足够你穿过。','船员日志 03：备用逃生舱已准备就绪。如果你看到了这段话，替我们看看地球。'];
function interact(){if(state.mode!=='playing')return;findInteraction();if(!closest){toast('靠近发光物体或控制器后按 E 交互。');return;}const {kind,obj}=closest;if(kind==='core'){if(obj.index===2&&!world.switchObj.active){toast('能源护罩仍然开启，请先操作上方控制器。');return;}obj.collected=true;obj.mesh.visible=false;state.coreCount++;state.energy=100;state.oxygen=Math.min(100,state.oxygen+12);sound('pickup');toast(`能源核心 ${String(obj.index+1).padStart(2,'0')} 已恢复 · 氧气 +12%`);if(obj.index<2){world.gates[obj.index].open=true;comms(obj.index===0?'第一枚核心在线，前方隔离门已打开。维修廊的激光并不稳定，留意它们的节奏。':'第二枚核心在线。反应堆控制器位于上方；别落进电弧区。');}else{comms('三个核心全部在线！逃生舱就在前方。07，我们回家。',9000);}updateMission();}else if(kind==='switch'){world.switchObj.active=true;world.switchObj.light.material=new T.MeshStandardMaterial({color:0x9cf3da,emissive:0x54ddad,emissiveIntensity:2});world.shield.visible=false;sound('open');toast('反应堆护罩已解除');comms('护罩关闭。翻回地板，取回最后一枚核心。');updateMission();}else if(kind==='log'){obj.taken=true;obj.mesh.visible=false;state.logCount++;sound('pickup');comms(logTexts[obj.index],13000);toast(`船员日志 ${state.logCount} / 3 已恢复`);}else if(kind==='exit'){if(state.coreCount<3){toast('需要恢复全部 3 枚能源核心，才能启动逃生舱。');return;}win();}findInteraction();updateHUD();}
function findInteraction(){const options=[];for(const o of world.cores)if(!o.collected&&distance(o)<2.1)options.push({kind:'core',obj:o,d:distance(o),text:o.index===2&&!world.switchObj.active?'护罩已锁定 · 寻找上方控制器':'回收能源核心'});if(!world.switchObj.active&&distance(world.switchObj)<2.1)options.push({kind:'switch',obj:world.switchObj,d:distance(world.switchObj),text:'解除反应堆护罩'});for(const o of world.logs)if(!o.taken&&distance(o)<1.8)options.push({kind:'log',obj:o,d:distance(o),text:'读取船员日志'});const exit={x:106.5,y:1.1,z:.8};if(distance(exit)<3)options.push({kind:'exit',obj:exit,d:distance(exit),text:state.coreCount===3?'启动逃生舱':'逃生舱 · 等待能源核心'});closest=options.sort((a,b)=>a.d-b.d)[0]||null;$('interact-prompt').classList.toggle('hidden',!closest||state.mode!=='playing');if(closest)$('interact-text').textContent=closest.text;}
function updateMission(){const s=sectors[state.sector];$('sector-code').textContent=`SECTOR 0${state.sector+1} / 03`;$('sector-name').textContent=s.name;$('sector-sub').innerHTML=`${s.en} <span>0${state.sector+1}</span>`;let objective=s.objective,hint=s.hint;if(state.coreCount===3){objective='前往逃生舱，启动撤离';hint='逃生舱位于飞船最右侧，靠近后按 E。';}else if(world.cores[state.sector].collected){objective='前往下一个舱段';hint='隔离门已打开，向右继续前进。';}else if(state.sector===2&&world.switchObj.active){objective='回收反应堆能源核心';hint='护罩已解除。核心位于地板，按 Q 返回。';}$('objective').textContent=objective;$('objective-hint').textContent=hint;for(let i=0;i<3;i++){ $('node-'+i).classList.toggle('collected',world.cores[i].collected);$('map-'+i).classList.toggle('active',i<=state.sector);}$('core-count').textContent=`${state.coreCount} / 3`;}
function updateHUD(){const time=formatTime(state.time).split(':');$('timer').innerHTML=`${time[0]}<span>:</span>${time[1]}`;$('timer').style.color=state.time<60?'#ff9466':'';$('oxygen-value').textContent=Math.ceil(state.oxygen);$('oxygen-bar').style.width=state.oxygen+'%';$('oxygen-bar').style.background=state.oxygen<25?'#ff9466':'';$('health-value').textContent=Math.ceil(state.health);$('health-bar').style.width=state.health+'%';$('energy-bar').style.width=state.energy+'%';$('gravity-arrow').textContent=state.gravity<0?'↓':'↑';$('gravity-label').textContent=state.gravity<0?'向下 · 地板':'向上 · 天花板';$('gravity-force').textContent=state.x>80&&state.x<90?'0.4 G':'1.0 G';$('gravity-btn').style.borderColor=state.gravity>0?'#7faaff77':'';$('map-player').style.left=Math.max(0,Math.min(89,(state.x-4)/104*89))+'%';$('route-percent').textContent=Math.min(100,Math.max(0,Math.round((state.x-4)/104*100)))+'%';}
function damage(amount,msg){if(state.invincible>0||state.mode!=='playing')return;state.health=Math.max(0,state.health-amount);state.invincible=1.4;cameraKick=.55;sound('hurt');$('damage-flash').style.opacity='.45';setTimeout(()=>$('damage-flash').style.opacity='0',240);if(msg)toast(msg);if(state.health<=0)lose('宇航服严重损坏','激光与电弧损坏了宇航服。留意红色光束的高度和开关节奏。');}
function showModal(kicker,title,html,actions){keys.clear();$('modal-kicker').textContent=kicker;$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal-actions').replaceChildren();for(const a of actions){const b=document.createElement('button');b.className=a.primary?'primary-btn':'secondary-btn';b.textContent=a.text;b.onclick=a.fn;$('modal-actions').append(b);}$('modal').classList.remove('hidden');$('interact-prompt').classList.add('hidden');setTimeout(()=>$('modal-actions').querySelector('button')?.focus(),50);}
function pause(){if(state.mode==='playing'){state.mode='paused';showModal('MISSION PAUSED','稍作喘息','<p>飞船的倒计时已暂停。准备好后，继续你的逃生任务。</p>',[{text:'继续撤离',primary:true,fn:resume},{text:'操作指南',fn:help}]);}else if(state.mode==='paused')resume();}
function resume(){if(state.mode!=='paused'&&state.mode!=='help')return;state.mode=started?'playing':'intro';$('modal').classList.add('hidden');keys.clear();lastTime=performance.now();}
function help(){helpPrevious=state.mode;if(state.mode==='playing'||state.mode==='intro'||state.mode==='paused'){state.mode='help';showModal('ASTRONAUT FIELD GUIDE','宇航员操作指南',`<div class="help-grid"><kbd>W A S D / 方向键</kbd><span>在舱室内移动，D / → 向前探索</span><kbd>Q</kbd><span>翻转重力，消耗 25% 电容</span><kbd>SPACE</kbd><span>跳跃；空中再次按下可推进</span><kbd>SHIFT</kbd><span>冲刺，额外消耗氧气</span><kbd>E</kbd><span>回收核心、读取日志、操作控制器</span><kbd>ESC</kbd><span>暂停 / 继续</span></div><p>重力电容会自动恢复。蓝色补给罐补充氧气，绿色罐修复宇航服。收集三个核心后，在逃生舱按 E 撤离。每进入新舱段会保存检查点。</p>`,[{text:'明白了',primary:true,fn:()=>{state.mode=helpPrevious==='paused'?'paused':helpPrevious;$('modal').classList.add('hidden');if(state.mode==='paused'){state.mode='playing';pause();}}}]);}}
function lose(title,reason){if(state.mode!=='playing')return;state.mode='lost';sound('hurt');showModal('SIGNAL LOST',title,`<p>${reason}</p><p>已恢复 ${state.coreCount} / 3 枚核心。你可以从最近的检查点继续，已收集的核心与日志会保留。</p>`,[{text:'从检查点重试',primary:true,fn:retry},{text:'重新开始',fn:reset}]);}
function retry(){state.x=state.checkpoint;state.y=1.08;state.z=.8;state.vx=state.vy=state.vz=0;state.gravity=-1;state.grounded=true;state.health=100;state.oxygen=85;state.energy=100;state.time=Math.max(180,state.time);state.invincible=3;state.mode='playing';keys.clear();$('modal').classList.add('hidden');comms('检查点已恢复。宇航服在线，继续撤离。');updateHUD();}
function reset(){Object.assign(state,{mode:'playing',x:4,y:1.08,z:.9,vx:0,vy:0,vz:0,gravity:-1,grounded:true,oxygen:100,health:100,energy:100,time:360,elapsed:0,flips:0,coreCount:0,logCount:0,sector:0,checkpoint:4,invincible:2,flipCooldown:0});for(const c of world.cores){c.collected=false;c.mesh.visible=true;}for(const g of world.gates){g.open=false;g.amount=0;}for(const s of world.supplies){s.taken=false;s.mesh.visible=true;}for(const l of world.logs){l.taken=false;l.mesh.visible=true;}world.switchObj.active=false;world.switchObj.light.material=new T.MeshStandardMaterial({color:0xff9364,emissive:0xff7043,emissiveIntensity:1.5});world.shield.visible=true;shownGap=shownSecond=shownFinal=shownLowG=shownOxygen=false;simTime=0;started=true;keys.clear();$('modal').classList.add('hidden');$('intro').classList.add('hidden');document.body.classList.add('playing');updateMission();updateHUD();comms('新的撤离任务已开始。D 前进，Q 翻转重力。');}
function win(){state.mode='won';const rank=state.elapsed<130&&state.logCount===3?'S':state.elapsed<180?'A':'B';sound('win');showModal('EXTRACTION SUCCESSFUL','欢迎回家，07。',`<p>逃生舱已脱离奥德赛号。远处的蓝色星球，正在等待最后一名归来的宇航员。</p><div class="result-stats"><span><b>${formatTime(state.elapsed)}</b>撤离用时</span><span><b>${state.flips}</b>重力翻转</span><span><b>${state.logCount} / 3</b>船员日志</span><span><b>${rank}</b>评级</span></div><p>${state.logCount===3?'全部日志已保存。奥德赛号的故事不会消失。':'再挑战一次，寻找全部 3 份船员日志。'}</p>`,[{text:'再次挑战',primary:true,fn:reset}]);try{if(!best||state.elapsed<best.time){best={time:state.elapsed,rank};localStorage.setItem('nullshift-best',JSON.stringify(best));}}catch{}}
function movementBlocked(x,z){const r=.34;for(const g of world.gates)if(!g.open&&Math.abs(x-g.x)<r+.25)return true;for(const o of world.obstacles)if(Math.abs(x-o.x)<o.w/2+r&&Math.abs(z-o.z)<o.d/2+r&&state.y-1.02<o.h-.08&&state.y+1.02>o.y)return true;return false;}
function physics(dt){if(state.mode!=='playing')return;state.elapsed+=dt;state.time-=dt;state.invincible=Math.max(0,state.invincible-dt);state.flipCooldown=Math.max(0,state.flipCooldown-dt);const sprint=keys.has('ShiftLeft')||keys.has('ShiftRight');let ax=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),az=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);const len=Math.hypot(ax,az);if(len){ax/=len;az/=len;}const speed=sprint?7:4.7;state.vx=T.MathUtils.damp(state.vx,ax*speed,10,dt);state.vz=T.MathUtils.damp(state.vz,az*speed,10,dt);let nx=T.MathUtils.clamp(state.x+state.vx*dt,-5,110.1),nz=T.MathUtils.clamp(state.z+state.vz*dt,-3.65,3.65);if(!movementBlocked(nx,state.z))state.x=nx;else state.vx=0;if(!movementBlocked(state.x,nz))state.z=nz;else state.vz=0;const prevY=state.y;const lowG=state.x>80&&state.x<90;state.vy+=state.gravity*(lowG?5.5:17)*dt;state.vy=T.MathUtils.clamp(state.vy,-18,18);state.y+=state.vy*dt;state.grounded=false;
let floorHeight=world.floors.some(([a,b])=>state.x>=a&&state.x<=b)?0:-Infinity;for(const o of world.obstacles)if(Math.abs(state.x-o.x)<o.w/2+.24&&Math.abs(state.z-o.z)<o.d/2+.24&&prevY-1.02>=o.h-.12)floorHeight=Math.max(floorHeight,o.h);if(state.vy<=0&&state.y-1.06<=floorHeight&&prevY-1.06>=floorHeight-.35){state.y=floorHeight+1.06;state.vy=0;state.grounded=state.gravity===-1;}if(state.vy>=0&&state.y+1.06>=8.5){state.y=7.44;state.vy=0;state.grounded=state.gravity===1;}if(state.y < -7){lose('失去飞船连接','你坠出了船体裂口。抵达裂口前按 Q 翻转重力，从完整的天花板通过。');return;}
state.energy=Math.min(100,state.energy+dt*(state.grounded?17:5));state.oxygen=Math.max(0,state.oxygen-dt*(.25+(sprint&&len?.2:0)));for(const h of world.hazards)if(h.active&&Math.abs(state.x-h.x)<.44&&Math.abs(state.y-h.y)<1.67){damage(17,'激光灼伤 · 切换到另一侧或等待熄灭');}if(state.x>76&&state.x<88&&state.y<.75)damage(35,'反应堆电弧 · 立即翻转重力');for(const s of world.supplies)if(!s.taken&&distance(s)<1.25){s.taken=true;s.mesh.visible=false;if(s.type==='oxygen'){state.oxygen=Math.min(100,state.oxygen+30);toast('氧气补给 +30%');}else{state.health=Math.min(100,state.health+35);toast('宇航服修复 +35%');}sound('pickup');}
if(state.time<=0){lose('撤离窗口已关闭','飞船已进入不可逆解体。利用冲刺通过安全区域，并提前规划重力路线。');return;}if(state.oxygen<=0){lose('氧气耗尽','氧气不足。寻找蓝色氧气罐，或减少长时间冲刺。');return;}const sector=state.x>71?2:state.x>36?1:0;if(sector>state.sector){state.sector=sector;state.checkpoint=sector===1?38:73;state.oxygen=Math.min(100,state.oxygen+15);state.health=Math.min(100,state.health+15);toast(`已抵达${sectors[sector].name} · 检查点已保存`);updateMission();}if(state.x>10&&!shownGap){shownGap=true;comms('前方地板断裂。按 Q 将重力切换为向上，沿天花板前进。',8500);}if(state.x>40&&!shownSecond){shownSecond=true;comms('第一束激光封锁下方，第二束封锁上方。中间有足够的空间切换重力。',8500);}if(state.x>74&&!shownFinal){shownFinal=true;comms('反应堆下方完全破损，必须从上方绕行。护罩控制器也在天花板附近。',8500);}if(lowG&&!shownLowG){shownLowG=true;toast('低重力区 0.4 G · 空中按 SPACE 使用推进器');}if(state.oxygen<25&&!shownOxygen){shownOxygen=true;comms('警告：氧气储量低于 25%。尽快寻找蓝色补给罐。');}findInteraction();}
function render(dt){const visualDt=state.mode==='playing'||state.mode==='intro'?dt:0;simTime+=visualDt;world.update(simTime,visualDt,state.x);const p=world.player;p.group.position.set(state.x,state.y,state.z);const desired=new T.Quaternion().setFromAxisAngle(new T.Vector3(0,0,1),state.gravity<0?0:Math.PI);p.pivot.quaternion.slerp(desired,1-Math.exp(-dt*5));const moving=Math.hypot(state.vx,state.vz);walkTime+=moving*visualDt*1.8;if(moving>.3){const face=Math.atan2(state.vx*(state.gravity>0?-1:1),state.vz);let delta=face-p.body.rotation.y;delta=Math.atan2(Math.sin(delta),Math.cos(delta));p.body.rotation.y+=delta*(1-Math.exp(-dt*8));}for(const l of p.limbs){const swing=state.grounded&&state.mode==='playing'?Math.sin(walkTime)*Math.min(.5,moving*.09)*l.s:.1*l.s;l.leg.rotation.x=swing;l.arm.rotation.x=-swing;l.arm.rotation.z=state.grounded?.06*l.s:.35*l.s;}p.body.position.y=state.grounded?Math.abs(Math.sin(walkTime))*.03:0;p.group.visible=!(state.invincible>0&&Math.floor(simTime*12)%2===0&&state.mode==='playing');
const aspect=innerWidth/innerHeight;const intro=state.mode==='intro'||(state.mode==='help'&&!started);let desiredCam=new T.Vector3(state.x-(intro?8:8.5),intro?10.6:10.4,aspect<1?24:18.5);const target=new T.Vector3(state.x+(intro?3.5:3),3.5,0);if(state.mode==='won'){desiredCam.y=15;desiredCam.z=22;}world.camera.position.lerp(desiredCam,1-Math.exp(-dt*3.3));cameraKick=Math.max(0,cameraKick-dt*1.8);world.camera.position.y+=Math.sin(simTime*40)*cameraKick*.07;world.camera.lookAt(target);
let targetObj=world.cores.find(c=>!c.collected);let title=`能源核心 0${(targetObj?.index??2)+1}`;if(state.sector===2&&!world.switchObj.active){targetObj=world.switchObj;title='护罩控制器';}if(!targetObj){targetObj={x:107,y:3,z:0};title='逃生舱 07';}const projected=new T.Vector3(targetObj.x,targetObj.y+.9,targetObj.z).project(world.camera);const screenX=(projected.x*.5+.5)*innerWidth,screenY=(-projected.y*.5+.5)*innerHeight;$('world-tag').style.left=Math.min(innerWidth-155,Math.max(innerWidth*.4,screenX))+'px';$('world-tag').style.top=Math.min(innerHeight-235,Math.max(innerWidth>800?290:220,screenY))+'px';$('target-label').textContent=title;$('target-distance').textContent=`${Math.ceil(distance(targetObj))} M`;$('world-tag').style.opacity=state.mode==='won'?'0':'.85';world.renderer.render(world.scene,world.camera);}
let hudFrames=0;function frame(now){const dt=Math.min(.05,(now-lastTime)/1000);lastTime=now;accumulator+=dt;while(accumulator>=1/90){physics(1/90);accumulator-=1/90;}render(dt);if(hudFrames++%8===0)updateHUD();requestAnimationFrame(frame);}requestAnimationFrame(frame);
$('start-btn').onclick=start;$('gravity-btn').onclick=()=>{if(state.mode==='intro')toast('点击「开始撤离」后，按 Q 翻转重力。');else flip();};$('pause-btn').onclick=()=>{if(state.mode==='intro')toast('开始撤离后可暂停。');else pause();};$('help-btn').onclick=help;$('sound-btn').onclick=()=>{setSound(!state.sound);sound('click');};
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)&&state.mode==='playing')e.preventDefault();if(e.code==='Escape'){if(state.mode==='help'){state.mode=helpPrevious;$('modal').classList.add('hidden');if(state.mode==='paused'){state.mode='playing';pause();}}else pause();return;}if(e.repeat)return;if(e.code==='Enter'&&state.mode==='intro'){e.preventDefault();start();return;}if(e.code==='KeyQ')flip();if(e.code==='Space')jump();if(e.code==='KeyE')interact();keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(state.mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.mode==='playing')pause();});window.addEventListener('resize',()=>world.resize());
for(const b of document.querySelectorAll('[data-key]')){const release=e=>{e.preventDefault();keys.delete(b.dataset.key);};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);});b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',()=>keys.delete(b.dataset.key));}for(const b of document.querySelectorAll('[data-action]'))b.addEventListener('pointerdown',e=>{e.preventDefault();({jump,interact,flip})[b.dataset.action]();});
$('modal').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const buttons=[...$('modal').querySelectorAll('button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}});
updateMission();updateHUD();$('loading').classList.add('hidden');
// Optional browser-native agent access shares exactly the visible controls.
if(document.modelContext?.registerTool){for(const tool of[{name:'read_escape_status',description:'读取当前逃生游戏状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments expected');return{mode:state.mode,sector:state.sector+1,cores:state.coreCount,oxygen:Math.ceil(state.oxygen),health:state.health,gravity:state.gravity,timeRemaining:Math.ceil(state.time)};}},{name:'set_escape_pause',description:'暂停或继续当前游戏，与暂停按钮行为相同。',inputSchema:{type:'object',properties:{paused:{type:'boolean'}},required:['paused'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.paused!=='boolean'||Object.keys(input).length!==1)throw Error('paused must be a boolean');if(input.paused&&state.mode==='playing')pause();else if(!input.paused&&state.mode==='paused')resume();else throw Error('Game is not in a pausable or resumable state');return{mode:state.mode};}}])try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}
